export function createRound(e){return{phase:"ready",elapsed:0,settled:0,seconds:e.seconds}}export function resetRound(e){return e.phase="ready",e.elapsed=0,e.settled=0,e}export function freePlay(e){return e.phase="free",e.elapsed=0,e.settled=0,e}export function isOver(e){return e.phase==="revenge"||e.phase==="settling"||e.phase==="done"}export function canBlow(e){return e.phase==="ready"||e.phase==="playing"||e.phase==="free"}export function timeLeft(e){return Math.max(0,e.seconds-e.elapsed)}export function stepRound(e,a,t,s){const l=a>0?a:0;return e.phase==="ready"?t.blowing?(e.phase="playing","start"):null:e.phase==="playing"?(e.elapsed+=l,e.elapsed>=e.seconds?(e.elapsed=e.seconds,e.settled=0,t.revenge?(e.phase="revenge","revenge"):(e.phase="settling","time-up")):null):e.phase==="revenge"?(e.settled+=l,t.revengeDone||e.settled>=s.revengeMax?(e.phase="settling",e.settled=0,"time-up"):null):e.phase==="settling"&&(e.settled+=l,t.moving===0&&e.settled>=s.settleMin||e.settled>=s.settleMax)?(e.phase="done","done"):null}
